import type { DiagramElement, Figure } from './figures';
import { C, FILL, bx, lb, ar, ln, ci, pg, sc, show, band, fresh, cover, flow } from './diagram-kit';

// 本試験対策 2027年2月号（担当B 25問）高校受験 理科の「動く図解」。キーは問題ID。座標は 320×240。
// 図は上（y＜165）に描き、下の帯（y≥170）に短い結論を出す。

/** 下の帯に一言（前のスライドの帯は白でおおいかくして書きかえる）。 */
const m = (text: string, color: string = C.main, fill: string = FILL.warm): DiagramElement[] =>
  band(170, bx(20, 176, 280, 34, text, color, fill, 12));

/** 表（文字入りの箱を並べる）。cw は列の幅、rh は行の高さ。 */
const grid = (rows: string[][], x0: number, y0: number, cw: number[], rh: number, size = 10, hiRow = -1, hiCol = -1): DiagramElement[] => {
  const out: DiagramElement[] = [];
  rows.forEach((r, i) => {
    let x = x0;
    r.forEach((t, j) => {
      const hi = i === hiRow || j === hiCol;
      out.push(bx(x, y0 + i * rh, cw[j], rh, t, hi ? C.red : i === 0 ? C.main : C.gray, hi ? FILL.red : i === 0 ? FILL.warm : '#FFFFFF', size));
      x += cw[j];
    });
  });
  return out;
};

const rad = (deg: number) => (deg * Math.PI) / 180;

// ═════════ 生物 ═════════

// k26 消化液
const digTable = (hi: number): DiagramElement[] => {
  const names = ['だ液', '胃液', '胆汁', 'すい液'];
  const jobs = ['デンプン\nだけ', 'タンパク質\nだけ', '酵素は\nない', '3つ\nすべて'];
  const out: DiagramElement[] = [];
  names.forEach((n, i) => {
    const x = 8 + i * 78;
    out.push(bx(x, 26, 72, 28, n, i === hi ? C.red : C.main, i === hi ? FILL.red : FILL.warm, 12));
    out.push(bx(x, 58, 72, 50, jobs[i], i === hi ? C.red : C.gray, i === hi ? FILL.red : '#FFFFFF', 10));
  });
  return out;
};
