// k33 根の細胞分裂の観察
const stages = (hi: number): DiagramElement[] => {
  const labs = ['オ\n核が見える', 'エ\nひも状に', 'ア\n中央に並ぶ', 'イ\n両はしへ', 'ウ\n仕切り'];
  const out: DiagramElement[] = [];
  labs.forEach((t, i) => {
    const x = 4 + i * 62;
    if (i > 0) out.push(ar(x - 6, 56, x - 1, 56, C.main));
    out.push(bx(x, 36, 52, 40, t, i <= hi ? C.red : C.gray, i <= hi ? FILL.red : '#FFFFFF', 8));
  });
  return out;
};
const f33 = show([
  { note: '根の先端を使って、細胞分裂を観察します。手順は、①うすい塩酸で温める ②染色液をたらす ③押しつぶす ④顕微鏡で観察する、です。', add: [...flow(['① 塩酸で\n温める', '② 染色液\nをたらす', '③ 押し\nつぶす', '④ 顕微鏡'], 50, { h: 44, size: 10, pad: 6, gap: 14, color: C.main, fill: FILL.warm }).flat(), ...m('根の先端→塩酸→染色→押しつぶす')] },
  { note: '❓塩酸で温めるのは、なぜでしょう。細胞どうしをつなぐものをとかして、細胞を1つ1つ、はなれやすくするためです。(1)の答えです。', add: fresh(bx(20, 30, 120, 44, '細胞どうしが\nくっついている', C.gray, FILL.gray, 10), ar(142, 52, 176, 52, C.red), lb(160, 42, '塩酸', 10, C.red, 'middle', true), bx(180, 30, 120, 44, '1つ1つ\nはなれやすい', C.green, FILL.green, 10), ...m('(1) 細胞をはなれやすくする', C.red, FILL.red)) },
  { note: '❓押しつぶすのは、なぜでしょう。細胞が重ならないように、1層に広げて、観察しやすくするためです。(2)の答えです。', add: fresh(bx(20, 30, 120, 44, '細胞が重なって\n見えにくい', C.gray, FILL.gray, 10), ar(142, 52, 176, 52, C.red), lb(160, 42, '押す', 10, C.red, 'middle', true), bx(180, 30, 120, 44, '1層に広がって\n見やすい', C.green, FILL.green, 10), ...m('(2) 1層に広げて見やすくする', C.red, FILL.red)) },
  { note: '❓酢酸オルセイン液で、赤くそまる部分はどこでしょう。核（染色体）です。分裂中の細胞では、染色体が赤く見えます。(3)の答えです。', add: fresh(ci(160, 74, 54, undefined, C.gray, FILL.gray), ci(160, 74, 22, '核', C.red, FILL.red, 13), lb(236, 70, '染色液で赤く', 10, C.red, 'start', true), lb(236, 84, 'そまる', 10, C.red, 'start', true), ...m('(3) 核（染色体）', C.red, FILL.red)) },
  { note: '❓分裂が進む順序は？ オ（核が見える・分裂前）→エ（染色体が太いひも状になって見え始める）→ア（中央に並ぶ）→イ（2つに分かれて両はしへ）→ウ（仕切りができて2つの細胞）です。(4)の答えです。', add: fresh(...stages(4), ...m('(4) オ→エ→ア→イ→ウ', C.red, FILL.red)) },
  { note: '❓根の先端近くで、細胞分裂がさかんな部分は何でしょう。成長点です。ここで細胞がふえて、根が長くのびます。(5)の答えです。', add: fresh(pg([[148, 16], [172, 16], [166, 110], [160, 132], [154, 110]], C.main, FILL.warm), ci(160, 122, 11, undefined, C.red, FILL.red), lb(184, 126, '成長点（先端近く）', 11, C.red, 'start', true), ...m('(5) 成長点', C.red, FILL.red)) },
  { note: '確かめます。染色体は、見えない→ひも状→中央に並ぶ→2つに分かれる→2つの細胞、と進みます。「並んでから分かれる」順序が合っています。', add: fresh(...stages(4), ...m('並んでから、分かれる', C.green, FILL.green)) },
], '答え：(1) 細胞をはなれやすくする (2) 1層に広げる (3) 核（染色体） (4) オ→エ→ア→イ→ウ (5) 成長点');

