// k45 月の出の遅れ
const moonFlow = (hi: number): DiagramElement[] => {
  const labs = ['満月', '下弦', '新月', '上弦'];
  const out: DiagramElement[] = [];
  labs.forEach((t, i) => {
    const x = 14 + i * 76;
    if (i > 0) out.push(ar(x - 12, 56, x - 2, 56, C.main));
    out.push(bx(x, 36, 62, 40, t, i === hi ? C.red : C.main, i === hi ? FILL.red : FILL.warm, 12));
  });
  return out;
};
