// k48 断層としゅう曲
const fx = (y: number) => 135 + (y - 45) * 0.5;
const faultBlocks = (shift: boolean): DiagramElement[] => {
  const cols = [FILL.yellow, FILL.green, FILL.blue];
  const out: DiagramElement[] = [];
  [55, 75, 95].forEach((y0, k) => {
    out.push(pg([[30, y0], [fx(y0), y0], [fx(y0 + 20), y0 + 20], [30, y0 + 20]], C.gray, cols[k]));
    const d = shift ? 20 : 0;
    const ya = y0 + d, yb = y0 + 20 + d;
    if (shift) out.push(pg([[fx(ya), ya], [290, ya], [290, yb], [fx(yb), yb]], C.gray, cols[k]));
    else out.push(pg([[fx(y0), y0], [290, y0], [290, y0 + 20], [fx(y0 + 20), y0 + 20]], C.gray, cols[k]));
  });
  out.push(ln(fx(45) - 2, 45, fx(125) + 2, 125, C.red, false, 2));
  return out;
};
